/* Home: the logo's lens grid is the stage; below it the lab reads like a lab — news first, then projects, then who we are. */
.hero { position: relative; min-height: min(100svh, 940px); display: grid; align-content: center; overflow: hidden; background: var(--bg); padding-block: calc(var(--nav-h) + 48px) 120px; isolation: isolate; }
.lens { position: absolute; inset: 0; width: 100%; height: 100%; z-index: -2; display: block; }
.hero::after { content: ""; position: absolute; inset: auto 0 0 0; height: 38%; background: linear-gradient(to bottom, rgba(0,0,0,0), #000); z-index: -1; pointer-events: none; }
.chrome { position: absolute; z-index: -1; pointer-events: none; transform: translate(calc(var(--mx, 0) * var(--k, 16px)), calc(var(--my, 0) * var(--k, 16px))); transition: transform 1.2s var(--ease); }
.chrome svg { display: block; width: 100%; height: auto; overflow: visible; }
.chrome.c1 { width: clamp(200px, 30vw, 460px); left: -9%; top: -2%; --k: -22px; }
.chrome.c2 { width: clamp(200px, 30vw, 460px); right: -4%; bottom: 10%; --k: 18px; }
.hero-in { display: grid; gap: 28px; justify-items: start; }
.hero-mark { margin: 0; display: grid; gap: 18px; }
.hero-mark svg { width: clamp(270px, 58vw, 820px); height: auto; color: var(--ink); display: block; }
.hero-lab { font: 600 clamp(20px, 2.6vw, 34px)/1 var(--f-wide); letter-spacing: -0.01em; color: var(--ink-2); }
.hero-what { font: 500 clamp(22px, 2.6vw, 32px)/1.2 var(--f-sans); letter-spacing: -0.01em; }
.hero-sub { max-width: 52ch; color: var(--ink-2); font-size: clamp(16px, 1.4vw, 18px); }
.hero-act { display: flex; flex-wrap: wrap; gap: 12px; }
.latest { position: absolute; left: 0; right: 0; bottom: 28px; }
.latest a { display: flex; align-items: baseline; gap: 16px; text-decoration: none; color: var(--ink-2); font-size: 15px; border-top: 1px solid var(--line-2); padding-top: 14px; }
.latest a:hover { color: var(--ink); }
.latest a:hover .ar { transform: translateX(4px); }
.latest .ar { transition: transform .35s var(--ease); margin-left: auto; }
.latest time { color: var(--muted); font: 400 13px var(--f-mono); white-space: nowrap; }

/* load sequence: everything ends in its resting place */
@media (prefers-reduced-motion: no-preference) {
  .hero-mark svg { animation: wipe 1.3s var(--ease) .15s both; }
  .hero-lab, .hero-what, .hero-sub, .hero-act, .latest { animation: up 1s var(--ease) both; }
  .hero-lab { animation-delay: .55s; } .hero-what { animation-delay: .7s; } .hero-sub { animation-delay: .82s; } .hero-act { animation-delay: .94s; } .latest { animation-delay: 1.1s; }
  .chrome.c1 .fly { animation: fly1 1.8s var(--ease) .2s both, drift1 14s ease-in-out 2s infinite alternate; }
  .chrome.c2 .fly { animation: fly2 1.8s var(--ease) .35s both, drift2 17s ease-in-out 2.2s infinite alternate; }
}
@keyframes wipe { from { clip-path: inset(0 0 100% 0); transform: translateY(14px); } to { clip-path: inset(0 0 0 0); transform: none; } }
@keyframes up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes fly1 { from { opacity: 0; transform: translate(-30%, 18%) rotate(-4deg); } to { opacity: 1; transform: none; } }
@keyframes fly2 { from { opacity: 0; transform: translate(26%, 20%) rotate(5deg); } to { opacity: 1; transform: none; } }
@keyframes drift1 { from { transform: translate(0, 0) rotate(0); } to { transform: translate(3%, -5%) rotate(-2.5deg); } }
@keyframes drift2 { from { transform: translate(0, 0) rotate(0); } to { transform: translate(-4%, 4%) rotate(2deg); } }

/* news */
.feature { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 48px; align-items: center; padding-bottom: 44px; border-bottom: 1px solid var(--line); }
.feature .kind { display: flex; gap: 14px; font: 400 13px/1 var(--f-mono); color: var(--muted); }
.feature h3 { font: 600 clamp(26px, 3vw, 38px)/1.1 var(--f-wide); letter-spacing: -0.02em; margin-top: 18px; }
.feature h3 em { font-style: normal; color: var(--aria); }
.feature p { color: var(--ink-2); margin-top: 16px; max-width: 48ch; }
.feature .more { margin-top: 24px; }
.dial { border: 1px solid var(--line); background: var(--bg-2); padding: 22px 22px 16px; }
.dial svg { display: block; width: 100%; height: auto; overflow: visible; }
.dial figcaption { font-size: 13px; color: var(--muted); margin-top: 10px; }
.news { list-style: none; margin: 0; padding: 0; }
.news a { display: grid; grid-template-columns: 120px 120px minmax(0, 1fr) 24px; gap: 16px; align-items: baseline; padding: 22px 0; border-bottom: 1px solid var(--line); text-decoration: none; transition: background-color .3s; }
.news a:hover { background: var(--bg-2); }
.news a:hover .ar { transform: translateX(4px); color: var(--ink); }
.news time { font: 400 13px var(--f-mono); color: var(--muted); }
.news .tag { font: 400 13px var(--f-mono); color: var(--ink-2); }
.news .t b { display: block; font-weight: 500; font-size: 18px; color: var(--ink); }
.news .t span { display: block; color: var(--ink-2); font-size: 15px; margin-top: 4px; }
.news .ar { color: var(--muted); transition: transform .35s var(--ease), color .25s; justify-self: end; }
.news li.soon-row a { cursor: default; }
.news li.soon-row a:hover { background: transparent; }

/* projects */
.projects { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.proj { display: grid; grid-template-rows: auto 1fr; border: 1px solid var(--line); text-decoration: none; color: var(--ink); transition: border-color .35s; }
.proj:hover { border-color: var(--line-2); }
.proj .stage { position: relative; aspect-ratio: 16 / 11; overflow: hidden; background: var(--bg-2); border-bottom: 1px solid var(--line);
  background-image: linear-gradient(var(--line) 1px, transparent 1px), linear-gradient(90deg, var(--line) 1px, transparent 1px); background-size: 48px 48px; background-position: -1px -1px; }
.proj .body { padding: 26px 26px 28px; display: grid; gap: 12px; align-content: start; }
.proj .row { display: flex; justify-content: space-between; gap: 12px; font: 400 13px/1.4 var(--f-mono); color: var(--muted); }
.proj h3 { font: 600 34px/1 var(--f-wide); letter-spacing: -0.02em; }
.proj p { color: var(--ink-2); font-size: 16px; }
.proj .more { width: fit-content; margin-top: 6px; }
.proj:hover .more .ar { transform: translateX(4px); }
.s-stage .phone { position: absolute; left: 50%; top: 12%; width: 38%; transform: translateX(-50%); border-radius: 26px; padding: 6px; background: #111; box-shadow: 0 0 0 1px #222; transition: transform .8s var(--ease); }
.s-stage .phone img { border-radius: 21px; width: 100%; aspect-ratio: 1179 / 2556; object-fit: cover; object-position: top; }
.proj:hover .s-stage .phone { transform: translateX(-50%) translateY(-3%); }
.proj h3.h-sionika { font: 400 44px/1 "Forum", serif; color: var(--sionika); letter-spacing: 0; }
.proj h3.h-aria { color: var(--aria); }
.a-stage svg { position: absolute; left: 6%; top: 50%; transform: translateY(-40%); width: 88%; height: auto; overflow: visible; }
.next { margin-top: 24px; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px 24px; padding: 20px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); color: var(--ink-2); font-size: 15px; }
.next b { color: var(--ink); font-weight: 500; }

/* about */
.about { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); gap: 56px; align-items: start; }
.about .big { font: 500 clamp(24px, 2.8vw, 36px)/1.3 var(--f-sans); letter-spacing: -0.015em; }
.about .big span { color: var(--ink-2); }
.princ { list-style: none; margin: 0; padding: 0; display: grid; }
.princ li { padding: 22px 0; border-top: 1px solid var(--line); display: grid; gap: 6px; }
.princ li:last-child { border-bottom: 1px solid var(--line); }
.princ b { font-weight: 500; font-size: 18px; }
.princ p { color: var(--ink-2); font-size: 15.5px; }
.facts { display: flex; flex-wrap: wrap; gap: 8px 28px; margin-top: 36px; font: 400 13px/1.5 var(--f-mono); color: var(--muted); }

/* contact */
.contact { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 24px 48px; align-items: end; }
.contact h2 { font: 600 clamp(34px, 6vw, 84px)/0.98 var(--f-wide); letter-spacing: -0.03em; }
.contact .acts { display: flex; flex-wrap: wrap; gap: 12px; }
.contact .handle { font: 500 15px var(--f-mono); color: var(--ink-2); margin-top: 18px; user-select: all; }

@media (max-width: 900px) {
  .feature, .about, .contact { grid-template-columns: minmax(0, 1fr); gap: 32px; }
