}
@media (max-width: 640px) {
  .hero { padding-block: calc(var(--nav-h) + 32px) 110px; min-height: 92svh; }
  .news a { grid-template-columns: minmax(0, 1fr) auto; gap: 6px 12px; padding: 18px 0; }
  .news time { grid-column: 1; grid-row: 1; }
  .news .tag { grid-column: 2; grid-row: 1; justify-self: end; }
  .news .t { grid-column: 1 / -1; }
  .news .ar { display: none; }
  .proj .body { padding: 20px; }
  .latest a span:not(.ar) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .chrome.c1 { width: 44vw; left: -16%; top: calc(var(--nav-h) + 3%); }
  .chrome.c2 { width: 48vw; right: -10%; bottom: 16%; }
}
