<script src="assets/lab.js"></script>
<script>
(() => {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();

  /* lens grid: the logo's fisheye grid, bending under the pointer */
  const hero = document.querySelector('.hero'), cv = document.getElementById('lens'), ctx = cv.getContext('2d');
  let W = 0, H = 0, step = 64, tx = .5, ty = .46, px = .5, py = .46, lastMove = -1e9, visible = true, raf = 0;
  const born = performance.now();
  function size() {
    const dpr = Math.min(2, devicePixelRatio || 1), r = cv.getBoundingClientRect();
    W = r.width; H = r.height; cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); step = W < 640 ? 46 : 66;
  }
  function warp(x, y, t) {
    const cx = W / 2, cy = H / 2, S = Math.hypot(W, H) / 2;
    const ux = (x - cx) / S, uy = (y - cy) / S, r2 = ux * ux + uy * uy;
    const k = .62 + .06 * Math.sin(t * .35);
    const f = (1 + k) / (1 + k * r2);
    let X = cx + ux * S * f, Y = cy + uy * S * f;
    const qx = px * W, qy = py * H, R = Math.min(W, H) * .36, dx = X - qx, dy = Y - qy, d = Math.hypot(dx, dy);
    if (d < R) { const s = 1 - d / R, g = .34 * s * s; X += dx * g; Y += dy * g; }
    return [X, Y];
  }
  function lines(t, color, width) {
    ctx.strokeStyle = color; ctx.lineWidth = width; ctx.beginPath();
    const cx = W / 2, cy = H / 2, nx = Math.ceil(W / step / 2) + 2, ny = Math.ceil(H / step / 2) + 2, seg = 14;
    for (let i = -nx; i <= nx; i++) {
      const x = cx + i * step;
      for (let y = cy - ny * step, j = 0; y <= cy + ny * step; y += seg, j++) { const [X, Y] = warp(x, y, t); j ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y); }
    }
    for (let i = -ny; i <= ny; i++) {
      const y = cy + i * step;
      for (let x = cx - nx * step, j = 0; x <= cx + nx * step; x += seg, j++) { const [X, Y] = warp(x, y, t); j ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y); }
    }
    ctx.stroke();
  }
  function frame(now) {
    const t = now / 1000, idle = now - lastMove > 2500;
    if (idle) { tx = .5 + .2 * Math.sin(t * .21); ty = .46 + .16 * Math.sin(t * .29 + 1); }
    px += (tx - px) * .05; py += (ty - py) * .05;
    ctx.clearRect(0, 0, W, H);
    ctx.globalAlpha = Math.min(1, (now - born) / 1400);
    lines(t, css('--grid'), 1);
    ctx.save(); ctx.beginPath(); ctx.arc(px * W, py * H, Math.min(W, H) * .3, 0, Math.PI * 2); ctx.clip();
    lines(t, '#3a3a3a', 1); ctx.restore();
    ctx.globalAlpha = 1;
    hero.style.setProperty('--mx', ((px - .5) * 2).toFixed(3)); hero.style.setProperty('--my', ((py - .5) * 2).toFixed(3));
    if (visible && !reduce) raf = requestAnimationFrame(frame);
  }
  size();
  if (reduce) { frame(performance.now() + 2000); }
  else {
    raf = requestAnimationFrame(frame);
    hero.addEventListener('pointermove', e => { const r = hero.getBoundingClientRect(); tx = (e.clientX - r.left) / r.width; ty = (e.clientY - r.top) / r.height; lastMove = performance.now(); }, { passive: true });
    new IntersectionObserver(([en]) => { visible = en.isIntersecting; if (visible) { cancelAnimationFrame(raf); raf = requestAnimationFrame(frame); } }).observe(hero);
  }
  addEventListener('resize', () => { size(); if (reduce) frame(performance.now() + 2000); });

  /* cents dial for the featured release, and the small one on the Aria project */
  const S = (tag, a = {}, text) => { const e = document.createElementNS('http://www.w3.org/2000/svg', tag); for (const k in a) e.setAttribute(k, a[k]); if (text !== undefined) e.textContent = text; return e; };
  function dial(svg, W, H, base, big) {
    const m = 16, x = v => m + (v + 50) / 100 * (W - 2 * m);
    svg.replaceChildren();
    for (let v = -50; v <= 50; v += 5) {
      const long = v % 25 === 0, len = v === 0 ? 30 : long ? 18 : 9;
      svg.append(S('line', { x1: x(v), x2: x(v), y1: base - len, y2: base, stroke: v === 0 ? '#fff' : '#5a5a5a', 'stroke-width': v === 0 ? 1.6 : 1 }));
      if (long && big) svg.append(S('text', { x: x(v), y: base + 20, 'text-anchor': 'middle', fill: '#7e7e7e', 'font-family': css('--f-mono'), 'font-size': 12 }, v === 0 ? '0' : (v > 0 ? '+' : '−') + Math.abs(v)));
    }
    svg.append(S('line', { x1: m, x2: W - m, y1: base, y2: base, stroke: '#2e2e2e' }));
    const needle = (v, color, label, h, right) => {
      const g = S('g', { class: 'needle', style: `--to:${x(v) - x(0)}px` });
      g.append(S('line', { x1: x(0), x2: x(0), y1: base - h, y2: base + 1, stroke: color, 'stroke-width': 2.5, 'stroke-linecap': 'round' }));
      g.append(S('circle', { cx: x(0), cy: base - h, r: 4.5, fill: color }));
      if (label) g.append(S('text', { x: x(0) + (right ? 10 : -10), y: base - h - 8, 'text-anchor': right ? 'start' : 'end', fill: '#f4f4f4', 'font-family': css('--f-sans'), 'font-size': big ? 14 : 12, 'font-weight': 500 }, label));
      g.setAttribute('transform', `translate(${x(v) - x(0)} 0)`);
      svg.append(g); return g;
    };
    const gt = needle(16, css('--gt'), big ? 'GuitarTuna +16' : '', big ? 40 : 30, true);
    const ar = needle(0, css('--aria'), big ? 'Aria 0' : '', big ? 56 : 42, false);
    return [ar, gt, x];
  }
  const dialEl = document.getElementById('dial'); // нет, если главная новость без шкалы
  const big = dialEl ? dial(dialEl, 520, 150, 100, true) : null;
  const small = dial(document.getElementById('mini'), 400, 90, 70, false);
  if (!reduce) {
    // needles settle like a real tuner when the panel comes into view (they rest at their final value)
    const settle = ([ar, gt, x], from) => {
      const t0 = performance.now(), A = x(from) - x(0), G = x(from + 16) - x(0);
      const tick = now => {
        const t = (now - t0) / 1000, damp = Math.exp(-3.2 * t) * Math.cos(9 * t);
        ar.setAttribute('transform', `translate(${(A * damp).toFixed(2)} 0)`);
        gt.setAttribute('transform', `translate(${(x(16) - x(0) + (G - (x(16) - x(0))) * damp).toFixed(2)} 0)`);
        if (t < 2.2) requestAnimationFrame(tick); else { ar.setAttribute('transform', 'translate(0 0)'); gt.setAttribute('transform', `translate(${x(16) - x(0)} 0)`); }
      };
      requestAnimationFrame(tick);
    };
    const seen = new WeakSet();
    const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting && !seen.has(e.target)) { seen.add(e.target); settle(e.target.id === 'dial' ? big : small, -22); } }), { threshold: .6 });
    if (dialEl) io.observe(dialEl);
    io.observe(document.getElementById('mini'));
  }
})();
</script>
</body>
</html>
